#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
TARGET_USER=${SUDO_USER:-${TARGET_USER:-$(id -un)}}
TARGET_HOME=${TWS_INSTALL_HOME:-$(getent passwd "$TARGET_USER" | cut -d: -f6)}
RUNTIME_DIR=/run/user/$(id -u "$TARGET_USER")
USER_BUS=unix:path=$RUNTIME_DIR/bus
DISPLAY_VAL=${DISPLAY:-:0}
# Generated by the shared framework owner; works without sibling downloads.
source "$SCRIPT_DIR/.installer-support/bootstrap.sh"
isc_load_helpers
isc_activate_components

# Install the workspace CLI, GNOME bridge and service with the selected target context.
# Parameters: none. Returns: zero after installation, nonzero on unavailable context/build resources.
install_task_workspaces() {
  printf 'parameters=none\n' >&2
  tws_validate_target || { printf '2\n' >&2; return 2; }
  tws_validate_command "${TWS_COMMAND:-tws}" || { printf '2\n' >&2; return 2; }
  local package binary command_name build_path bootstrap extension current launcher_schema current_launcher launcher_hotkey
  binary=${TWS_BINARY:-$SCRIPT_DIR/target/release/tws}
  if [[ -n ${TWS_BINARY:-} ]]; then
    tws_validate_binary "$binary" || { printf '2\n' >&2; return 2; }
  fi
  SUDO_REQUIRED_STEPS=()
  for package in tmux libglib2.0-bin libgtk-3-bin kitty build-essential curl ca-certificates; do
      if ! dpkg-query -W -f='${Status}' "$package" 2>/dev/null | grep -q 'install ok installed'; then
          if is_root && [[ ${TWS_INSTALL_OFFLINE:-0} != 1 ]]; then
              apt_install "$package" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
          else
              SUDO_REQUIRED_STEPS+=("sudo apt-get install -y $package")
          fi
      fi
  done
  command_name=${TWS_COMMAND:-tws}
  if [[ -z ${TWS_BINARY:-} ]]; then
      build_path="$TARGET_HOME/.cargo/bin:$PATH"
      if ! run_as_target env PATH="$build_path" sh -c 'command -v cargo >/dev/null'; then
          if [[ ${TWS_INSTALL_OFFLINE:-0} == 1 ]]; then
              printf 'Offline build requires Rust 1.85+, or TWS_BINARY=/path/to/prebuilt/tws.\n' >&2
              printf '1\n' >&2
              return 1
          fi
          bootstrap=$(mktemp) || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
          curl --proto '=https' --tlsv1.2 -fsSL https://sh.rustup.rs -o "$bootstrap" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
          chmod 644 "$bootstrap" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
          if ! run_as_target env CARGO_HOME="$TARGET_HOME/.cargo" RUSTUP_HOME="$TARGET_HOME/.rustup" \
              sh "$bootstrap" -y --profile minimal --no-modify-path; then
              rm -f "$bootstrap"
              printf '1\n' >&2
              return 1
          fi
          rm -f "$bootstrap"
      fi
      run_as_target env PATH="$build_path" CARGO_HOME="$TARGET_HOME/.cargo" RUSTUP_HOME="$TARGET_HOME/.rustup" \
          cargo build --manifest-path "$SCRIPT_DIR/Cargo.toml" --locked --release || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  fi
  tws_validate_binary "$binary" || { printf '2\n' >&2; return 2; }
  extension="$TARGET_HOME/.local/share/gnome-shell/extensions/task-workspaces@local"
  run_as_target mkdir -p "$extension" "$TARGET_HOME/.local/bin" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  run_as_target cp "$SCRIPT_DIR/extension/extension.js" "$SCRIPT_DIR/extension/geometry.js" "$SCRIPT_DIR/extension/metadata.json" "$extension/" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  run_as_target install -m 755 "$binary" "$TARGET_HOME/.local/bin/tws" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  if [[ "$command_name" != tws ]]; then
      run_as_target install -m 755 "$binary" "$TARGET_HOME/.local/bin/$command_name" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  fi
  run_as_target mkdir -p "$TARGET_HOME/.config/systemd/user" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  unit=$(mktemp) || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  trap 'rm -f "$unit"' EXIT
  cat > "$unit" <<UNIT
[Unit]
Description=Keep named task workspaces and always-on windows available
After=graphical-session.target
PartOf=graphical-session.target
[Service]
ExecStart="$TARGET_HOME/.local/bin/tws" _watch
ExecStop="$TARGET_HOME/.local/bin/tws" _checkpoint-all
KillMode=process
Restart=on-failure
RestartSec=10
[Install]
WantedBy=graphical-session.target
UNIT
  run_as_target install -m 644 "$unit" "$TARGET_HOME/.config/systemd/user/task-workspaces.service" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  if [[ ${TWS_INSTALL_OFFLINE:-0} != 1 ]]; then
      if ! run_as_target gnome-extensions enable task-workspaces@local; then
          current=$(run_as_target gsettings get org.gnome.shell enabled-extensions)
          if [[ "$current" != *"'task-workspaces@local'"* ]]; then
              if [[ "$current" == '[]' || "$current" == '@as []' ]]; then
                  current="['task-workspaces@local']"
              else
                  current="${current%]}, 'task-workspaces@local']"
              fi
              run_as_target gsettings set org.gnome.shell enabled-extensions "$current" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
          fi
          printf 'Extension registered for next login; GNOME will discover it after logout/login on Wayland.\n'
      fi
      run_as_target gsettings get org.gnome.shell enabled-extensions || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
      launcher_schema='org.gnome.settings-daemon.plugins.media-keys.custom-keybinding:/org/gnome/settings-daemon/plugins/media-keys/custom-keybindings/tws-configuration-launcher/'
      current_launcher=$(run_as_target gsettings get "$launcher_schema" binding)
      if [[ ${TWS_CONFIG_HOTKEY:-} != none ]] &&
         { [[ -n ${TWS_CONFIG_HOTKEY:-} ]] || [[ "$current_launcher" == "''" ]]; }; then
          launcher_hotkey=${TWS_CONFIG_HOTKEY:-Control+Alt+Super+W}
          if ! run_as_target "$TARGET_HOME/.local/bin/$command_name" configure --launcher "$launcher_hotkey"; then
              printf 'Configuration shortcut unavailable; choose one with: tws configure --launcher HOTKEY\n'
          fi
      fi
      run_as_target systemctl --user daemon-reload || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
      run_as_target systemctl --user enable task-workspaces.service || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
      run_as_target systemctl --user restart task-workspaces.service || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  fi
  printf 'Installed %s/.local/bin/tws\n' "$TARGET_HOME"
  if ((${#SUDO_REQUIRED_STEPS[@]})); then
      printf 'Root-only dependencies pending:\n'
      printf '  %s\n' "${SUDO_REQUIRED_STEPS[@]}"
  fi
  run_as_target mkdir -p "$TARGET_HOME/.local/state/task-workspaces" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  printf '%s\n' "$command_name" > "$unit"
  run_as_target install -m 600 "$unit" "$TARGET_HOME/.local/state/task-workspaces/installer-command" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  printf '0\n' >&2
  return 0
}

# Require a non-root desktop account and a concrete target home for mutations.
# Parameters: none. Returns: zero for the accepted target, two otherwise.
tws_validate_target() {
  printf 'parameters=none\n' >&2
  if [[ -z "$TARGET_USER" || "$TARGET_USER" == root || -z "$TARGET_HOME" || "$TARGET_HOME" != /* ]]; then
    printf 'Set TARGET_USER to the desktop user and provide an absolute target home.\n2\n' >&2
    return 2
  fi
  printf '0\n' >&2
  return 0
}

# Accept a command name that stays in the target binary directory.
# Parameters: $1 - configured command name. Returns: zero, or two for an unsafe name.
tws_validate_command() {
  printf 'command_name=%s\n' "$1" >&2
  if [[ ! "$1" =~ ^[a-zA-Z][a-zA-Z0-9_-]*$ ]]; then
    printf 'Invalid TWS_COMMAND\n2\n' >&2
    return 2
  fi
  printf '0\n' >&2
  return 0
}

# Require an available executable before copying any installation artifacts.
# Parameters: $1 - resolved prebuilt or freshly built binary path. Returns: zero, or two for unavailable binaries.
tws_validate_binary() {
  printf 'binary=%s\n' "$1" >&2
  if [[ ! -f "$1" || ! -x "$1" ]]; then
    printf 'Task Workspaces binary is not an executable file: %s\n2\n' "$1" >&2
    return 2
  fi
  printf '0\n' >&2
  return 0
}

# Inspect only owned files to report whether the runtime is installed.
# Parameters: none. Returns: zero when binary, extension and service are present, one otherwise.
detect_task_workspaces() {
  printf 'parameters=none\n' >&2
  local status=1
  if [[ -x "$TARGET_HOME/.local/bin/tws" && -f "$TARGET_HOME/.local/share/gnome-shell/extensions/task-workspaces@local/metadata.json" && -f "$TARGET_HOME/.config/systemd/user/task-workspaces.service" ]]; then
    status=0
  fi
  printf '%s\n' "$status" >&2
  return "$status"
}

# Parse the installer-owned alias receipt without interpreting shell content.
# Parameters: none. Returns: zero and TWS_INSTALLED_COMMAND, or two for malformed metadata.
tws_parse_installed_command() {
  printf 'parameters=none\n' >&2
  TWS_INSTALLED_COMMAND=tws
  local receipt="$TARGET_HOME/.local/state/task-workspaces/installer-command"
  if [[ -f "$receipt" ]]; then
    IFS= read -r TWS_INSTALLED_COMMAND < "$receipt" || true
    if [[ ! "$TWS_INSTALLED_COMMAND" =~ ^[a-zA-Z][a-zA-Z0-9_-]*$ ]]; then
      printf 'Invalid installer command receipt\n2\n' >&2
      return 2
    fi
  fi
  printf 'command_name=%s status=0\n' "$TWS_INSTALLED_COMMAND" >&2
  return 0
}

# Remove installed runtime files while retaining saved workspace profiles and sessions.
# Parameters: none. Returns: zero after repeatable removal, nonzero on invalid context or command failures.
uninstall_task_workspaces() {
  printf 'parameters=none\n' >&2
  tws_validate_target || { printf '2\n' >&2; return 2; }
  tws_parse_installed_command || { printf '2\n' >&2; return 2; }
  local extension="$TARGET_HOME/.local/share/gnome-shell/extensions/task-workspaces@local"
  if [[ ${TWS_INSTALL_OFFLINE:-0} != 1 ]]; then
    if [[ -f "$TARGET_HOME/.config/systemd/user/task-workspaces.service" ]]; then
      run_as_target systemctl --user disable --now task-workspaces.service || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
    fi
    if [[ -x "$TARGET_HOME/.local/bin/tws" ]]; then
      run_as_target "$TARGET_HOME/.local/bin/tws" configure --launcher '' || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
    fi
    run_as_target gnome-extensions disable task-workspaces@local || true
  fi
  run_as_target rm -f -- "$TARGET_HOME/.local/bin/tws" "$TARGET_HOME/.config/systemd/user/task-workspaces.service" \
    "$extension/extension.js" "$extension/geometry.js" "$extension/metadata.json" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  if [[ "$TWS_INSTALLED_COMMAND" != tws ]]; then
    run_as_target rm -f -- "$TARGET_HOME/.local/bin/$TWS_INSTALLED_COMMAND" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  fi
  run_as_target rmdir -- "$extension" 2>/dev/null || true
  run_as_target rm -f -- "$TARGET_HOME/.local/state/task-workspaces/installer-command" || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  if [[ ${TWS_INSTALL_OFFLINE:-0} != 1 ]]; then
    run_as_target systemctl --user daemon-reload || { local status=$?; printf '%s\n' "$status" >&2; return "$status"; }
  fi
  printf '0\n' >&2
  return 0
}

source "$SCRIPT_DIR/installer/components.sh"
component_main "$@"
